INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35811, 'John 5:10', 'John', 5, 10, 'نو د یهودیانو مشرانو هغه روغ شوي سړي ته وویل: «دا د سبت ورځ ده، د سبت په ورځ تاته روا نه ده چې خپله بستره یوسې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_10.mp3', '', 1761754199, 1761754199),
(35812, 'John 5:11', 'John', 5, 11, 'خو هغه ځواب ورکړ: «کوم سړي چې زه روغ کړم ماته یې وویل چې خپله بستره دې واخله او وګرځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_11.mp3', '', 1761754199, 1761754199),
(35813, 'John 5:12', 'John', 5, 12, 'هغوی د هغه نه پوښتنه وکړه: «هغه سړی څوک دی چې تاته یې وویل چې بستره دې واخله او وګرځه؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_12.mp3', '', 1761754199, 1761754199),
(35814, 'John 5:13', 'John', 5, 13, 'خو هغه سړی چې روغ شوی ؤ نه پوهېده چې عیسی څوک دی، ځکه چې په هغه ځای کې ډېره ګڼه‌ګوڼه وه او عیسی ځان ویستلی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_13.mp3', '', 1761754199, 1761754199),
(35815, 'John 5:14', 'John', 5, 14, 'وروسته بیا عیسی هغه سړی د خدای په کور کې پیدا کړ او ورته ویې ویل: «ګوره، اوس چې ښه شوی یې نو نوره ګناه مه کوه، که نه نو د دې نه به هم د زیاتو کړاوونو سره مخ شې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_14.mp3', '', 1761754199, 1761754199),
(35816, 'John 5:15', 'John', 5, 15, 'هغه سړی لاړ او د یهودیانو مشرانو ته یې خبر ورکړ: «چا چې زه روغ کړی وم هغه عیسی ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_15.mp3', '', 1761754199, 1761754199),
(35817, 'John 5:16', 'John', 5, 16, 'په دې خاطر چې عیسی د سبت په ورځ داسې کارونه کول، نو د یهودیانو مشرانو د هغه په ځورولو پیل وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_16.mp3', '', 1761754199, 1761754199),
(35818, 'John 5:17', 'John', 5, 17, 'خو عیسی هغوی ته وویل: «زما پلار تل داسې کارونه کړي دي، نو زه هم همداسې کوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_17.mp3', '', 1761754199, 1761754199),
(35819, 'John 5:18', 'John', 5, 18, 'د عیسی په دې خبره د یهودیانو مشرانو هڅه وکړه چې هغه ووژني، ځکه چې یوازې دا نه چې هغه د سبت قانون مات کړی دی بلکې په دې هم چې هغه خدای ته خپل پلار ووایه او په دې ډول یې خپل ځان د خدای سره برابر وګاڼه. د زوی واک او اختیار', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_18.mp3', '', 1761754199, 1761754199),
(35820, 'John 5:19', 'John', 5, 19, 'عیسی هغوی ته په ځواب کې وویل: «په یقین سره زه تاسو ته دا وایم چې زوی نه شي کولای چې له خپله ځانه کوم کار وکړي، بلکې یوازې هغه کار کوي چې هغه یې ویني چې پلار یې کوي. څه چې پلار کوي هغه زوی هم کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_19.mp3', '', 1761754199, 1761754199),
(35821, 'John 5:20', 'John', 5, 20, 'ځکه چې زوی په پلار باندې ګران وي او هغه چې خپله کوم کارونه کوي هغه ټول زوی ته ورښایي. برسېره پر‌دې نور لوی لوی کارونه هم ورته وروښایي او تاسو ټول به ورته حیران پاتې شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_20.mp3', '', 1761754199, 1761754199),
(35822, 'John 5:21', 'John', 5, 21, 'ځکه لکه څنګه چې پلار مړي راژوندي کوي او هغوی ته ژوند ورکوي، نو په همدې ډول زوی هم چې هرچا ته وغواړي ژوند ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_21.mp3', '', 1761754199, 1761754199),
(35823, 'John 5:22', 'John', 5, 22, 'همدارنګه پلار د هېچا په هکله قضاوت نه کوي بلکې خپل زوی ته یې پوره حق ورکړی دی چې قضاوت وکړي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_22.mp3', '', 1761754199, 1761754199),
(35824, 'John 5:23', 'John', 5, 23, 'ترڅو لکه څنګه چې ټول د پلار درناوی کوي، هماغسې د زوی درناوی هم وکړي. څوک چې د زوی عزت نه کوي، نو د هغه د پلار چې هغه یې رالېږلی دی هم عزت نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_23.mp3', '', 1761754199, 1761754199),
(35825, 'John 5:24', 'John', 5, 24, 'په یقین سره زه تاسو ته دا وایم څوک چې زما خبرو ته غوږ نیسی او په هغه چا باندې ایمان راوړي چې زه یې رالېږلی یم، نو هغه تلپاتې ژوندون لري. هغه به محاکمه نه شي، بلکې هغه لا پخوا د مرګ نه تېر شوی او ژوند یې پیل کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_24.mp3', '', 1761754199, 1761754199),
(35826, 'John 5:25', 'John', 5, 25, 'په یقین سره زه تاسو ته دا وایم چې هغه وخت به راشي، بلکې راغلی دی چې مړي به د خدای د زوی اواز اوري او هرڅوک یې چې واوري هغه به راژوندی شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_25.mp3', '', 1761754199, 1761754199),
(35827, 'John 5:26', 'John', 5, 26, 'لکه څنګه چې پلار هغه ذات دی چې انسانانو ته ژوند ورکوي، نو زوی ته یې هم دا قدرت ورکړی دی چې انسانانو ته ژوند ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_26.mp3', '', 1761754199, 1761754199),
(35828, 'John 5:27', 'John', 5, 27, 'هغه زوی ته دا واک او اختیار ورکړی دی چې قضاوت وکړي، ځکه چې د انسان زوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_27.mp3', '', 1761754199, 1761754199),
(35829, 'John 5:28', 'John', 5, 28, 'په دې باندې مه حیرانېږئ، ځکه چې هغه وخت به راشي چې ټول مړي به په قبرونو کې د هغه اواز واوري', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_28.mp3', '', 1761754199, 1761754199),
(35830, 'John 5:29', 'John', 5, 29, 'او د خپلو قبرونو نه به راووځي. کومو خلکو چې نېک کارونه کړي وي هغوی به راپورته شي او ژوند به کوي او کومو خلکو چې بد کارونه کړي دي هغوی به راپورته شي او سزا به ورته ورکول کیږي. د عیسی په هکله شاهدي ورکول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_29.mp3', '', 1761754199, 1761754199),
(35831, 'John 5:30', 'John', 5, 30, 'زه په خپل اختیار هېڅ نه شم کولای. زه د خلکو په هکله هغه قضاوت کوم چې د خپل پلار نه یې اورم. نو کله چې د هغوی په هکله قضاوت کوم هغه قضاوت د انصاف له مخې وي، ځکه چې زه خپله رضا نه بلکې د هغه چا رضا پوره کوم چې زه یې رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_30.mp3', '', 1761754199, 1761754199),
(35832, 'John 5:31', 'John', 5, 31, 'که چېرې زه د خپل ځان په هکله شاهدي ورکړم نو دا شاهدي رښتیا نه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_31.mp3', '', 1761754199, 1761754199),
(35833, 'John 5:32', 'John', 5, 32, 'خو یو بل څوک شته چې زما په هکله شاهدي ورکوي او زه پوهېږم هغه چې زما په هکله شاهدي ورکوي هغه رښتیا دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_32.mp3', '', 1761754199, 1761754199),
(35834, 'John 5:33', 'John', 5, 33, 'تاسو یحیی ته استازي ورلېږلي وو او هغه چې زما په هکله کومه شاهدي ورکړه هغه رښتیا وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_33.mp3', '', 1761754199, 1761754199),
(35835, 'John 5:34', 'John', 5, 34, 'زه په رښتیا سره د انسانانو شاهدۍ ته چې دا ثابته کړي چې زه څوک یم اړتیا نه لرم، بلکې دا خبرې د دې دپاره درته کوم چې تاسو خلاصون ومومئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_34.mp3', '', 1761754199, 1761754199),
(35836, 'John 5:35', 'John', 5, 35, 'یحیی د یو څراغ په شان ؤ چې بلېده او رڼا یې کوله. تاسو تیار وئ چې د یو څه وخت دپاره د هغه خبرې په خوشحالۍ سره واورئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_35.mp3', '', 1761754199, 1761754199),
(35837, 'John 5:36', 'John', 5, 36, 'خو زه د یحیی نه لوی شاهد لرم. کوم کارونه چې پلار ماته سپارلي دي چې سرته یې ورسوم، د دې شاهدي ورکوي چې پلار زه رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_36.mp3', '', 1761754199, 1761754199),
(35838, 'John 5:37', 'John', 5, 37, 'پلار چې زه یې رالېږلی یم په خپله یې زما په هکله شاهدي ورکړې ده. تاسو هېڅکله د هغه څېره نه ده لیدلې او نه مو د هغه اواز اورېدلی دی،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_37.mp3', '', 1761754199, 1761754199),
(35839, 'John 5:38', 'John', 5, 38, 'او د هغه کلام ستاسو په زړونو کې ځای نه دی موندلی، ځکه چې تاسو په هغه چا باندې چې هغه رالېږلی دی ایمان نه راوړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_38.mp3', '', 1761754199, 1761754199),
(35840, 'John 5:39', 'John', 5, 39, 'تاسو د خدای کلام په ځیر سره لولئ، ځکه چې فکر کوئ چې د هغه په وسیله به تلپاتې ژوندون ومومئ. همدا لیکنې زما په هکله شاهدي ورکوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_39.mp3', '', 1761754199, 1761754199),
(35841, 'John 5:40', 'John', 5, 40, 'خو بیاهم تاسو نه غواړئ چې ماته راشئ ترڅو تلپاتې ژوندون ولرئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_40.mp3', '', 1761754199, 1761754199),
(35842, 'John 5:41', 'John', 5, 41, 'زه د خلکو نه د درناوي تمه نه لرم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_41.mp3', '', 1761754199, 1761754199),
(35843, 'John 5:42', 'John', 5, 42, 'خو زه تاسو پېژنم چې ستاسو په زړونو کې د خدای سره مینه نشته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_42.mp3', '', 1761754199, 1761754199),
(35844, 'John 5:43', 'John', 5, 43, 'زه د خپل پلار په نوم راغلی یم او تاسو ما نه منئ، خو که بل څوک په خپل نوم راشي نو تاسو به یې ومنئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_43.mp3', '', 1761754199, 1761754199),
(35845, 'John 5:44', 'John', 5, 44, 'تاسو چې د یو بل نه د درناوي تمه لرئ او د هغه درناوي په لټه کې نه یئ چې د یوازېني خدای له خوا دی، نو بیا څنکه کولای شئ چې په ما باندې ایمان ولرئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_44.mp3', '', 1761754199, 1761754199),
(35846, 'John 5:45', 'John', 5, 45, 'خو دا فکر مه کوئ چې زه به تاسو د خپل پلار په حضور کې ملامته کړم، همدا موسی چې تاسو ورته هیله لرئ، هماغه به تاسو ملامته کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_45.mp3', '', 1761754199, 1761754199),
(35847, 'John 5:46', 'John', 5, 46, 'که چېرې تاسو په موسی باندې ایمان درلودلی، نو په ما باندې به مو هم ایمان درلود، ځکه چې هغه زما په هکله لیکلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_46.mp3', '', 1761754199, 1761754199),
(35848, 'John 5:47', 'John', 5, 47, 'خو که چېرې تاسو د هغه په لیکنې باندې ایمان نه لرئ، نو زما په خبرو باندې به څنګه باور وکړئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_47.mp3', '', 1761754199, 1761754199),
(35849, 'Mark 12:1', 'Mark', 12, 1, 'بیا عیسی هغوی ته په مثالونو کې خبرې پیل کړې: «یو سړي د انګورو باغ جوړ کړ او دېوال یې ورڅخه تاو کړ، د انګورو د شربت د ویستلو دپاره یې په کې یو ځای جوړ کړ او د څارنې دپاره یې په کې یو برج هم جوړ کړ. بیا یې هغه باغوانانو ته په اجاره ورکړ او خپله په سفر روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_1.mp3', '', 1761754199, 1761754199),
(35850, 'Mark 12:2', 'Mark', 12, 2, 'کله چې د انګورو د راټولولو وخت راورسېد، نو هغه خپل یو نوکر باغوانانو ته ورولېږه چې خپله برخه انګور ترې واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_2.mp3', '', 1761754199, 1761754199),
(35851, 'Mark 12:3', 'Mark', 12, 3, 'خو باغوانانو هغه نوکر ونیوه، هغه یې وواهه او تش لاس یې بېرته ولېږه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_3.mp3', '', 1761754199, 1761754199),
(35852, 'Mark 12:4', 'Mark', 12, 4, 'بیا هغه یو بل نوکر ورولېږه. هغه یې هم په سر سر وواهه او بې‌عزته یې کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_4.mp3', '', 1761754199, 1761754199),
(35853, 'Mark 12:5', 'Mark', 12, 5, 'بیا هغه بل نوکر ورولېږه او هغه یې مړ کړ. هغه نور ډېر نوکران هم ورولېږل، خو ځینې یې ووهل او ځینې یې مړه کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_5.mp3', '', 1761754199, 1761754199),
(35854, 'Mark 12:6', 'Mark', 12, 6, 'یوازېنی کس چې ورته پاتې ؤ چې ور ویې لېږي هغه یې خپل ګران زوی ؤ. په پای کې یې خپل زوی ورولېږه او فکر یې وکړ چې هغوی به زما د زوی لحاظ وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_6.mp3', '', 1761754199, 1761754199),
(35855, 'Mark 12:7', 'Mark', 12, 7, 'خو باغوانانو یو بل ته وویل: ‹دا یې وارث دی، راځئ چې مړ یې کړو او میراث به یې زمونږ شي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_7.mp3', '', 1761754199, 1761754199),
(35856, 'Mark 12:8', 'Mark', 12, 8, 'نو هغوی هغه ونیوه او مړ یې کړ او د هغه مړی یې د انګورو د باغ څخه دباندې وغورځاوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_8.mp3', '', 1761754199, 1761754199),
(35857, 'Mark 12:9', 'Mark', 12, 9, 'عیسی پوښتنه وکړه: «د باغ خاوند به اوس څه کوي؟ هغه به راشي او باغوانان به ووژني او باغ به نورو ته ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_9.mp3', '', 1761754199, 1761754199),
(35858, 'Mark 12:10', 'Mark', 12, 10, 'ایا تاسو د خدای په کلام کې دا نه دي لوستلي: کومه تیږه چې رد کړې ګلکارانو وه هغه اوس شوه اصلي تیږه د تهداب', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark12_verse_10.mp3', '', 1761754199, 1761754199),
